document.addEventListener("DOMContentLoaded",function(){document.getElementById("botonRegistrarse").addEventListener("click",function(){window.location.href=`${URLMadre}/registrarse`}),document.getElementById("formularioAut").addEventListener("submit",function(e){e.preventDefault();const t=new FormData(this),n={};t.forEach((e,t)=>{n[t]=e}),fetch("aut/iniciar",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(n)}).then(e=>{if(!e.ok)throw new Error("Error en la solicitud");return e.json()}).then(({estado:e,mensaje:t})=>{if("exitoso"==e)window.location.href=`${URLMadre}/exito?mensaje=${t}`;else{const e=document.getElementById("mensajeAlerta");e.style="color: #d7596d;",e.innerText=t,setTimeout(function(){e.innerText=""},5e3)}}).catch(e=>{console.error(e),window.location.href=`${URLMadre}/error?mensaje=${e}`})})});